def generate_batch11() -> List[Dict]:
    chunks = []
    for item in DATA:
        sub = "training_concepts"
        if "评估" in item["title"]: sub = "assessment"
        elif "预防" in item["title"]: sub = "injury_prevention"
        elif "调整" in item["title"]: sub = "plan_adjustment"
        elif "免疫" in item["title"] or "睡眠" in item["title"]: sub = "recovery_science"
        chunks.append(make_chunk(category="methodology", subcategory=sub, title=item["title"], content=item["content"], keywords=item["keywords"]))
    return chunks


if __name__ == "__main__":
    chunks = generate_batch11()
    print(f"生成 {len(chunks)} chunks (batch11)")
